import pytest
@pytest.mark.parametrize('age,expected', [(25, True), (18, True), (10, False)])
def test_is_adult(age, expected):
    assert (age >= 18) == expected

from unittest.mock import Mock
api = Mock()
api.get_user.return_value = {'name': 'Kakade'}
assert api.get_user(1) == {'name': 'Kakade'}
assert api.get_user.called

from fastapi import FastAPI
from fastapi.testclient import TestClient
app = FastAPI()
@app.get('/users/{name}')
def get_user(name: str):
    return {'name': name}
client = TestClient(app)
r = client.get('/users/Kakade')
assert r.status_code == 200
assert r.json() == {'name': 'Kakade'}
